"\"\"\"E1 — Prédiction du champ de poids du parent : le prior jacobien achète-t-il l'interpolation ?\n\nLe parent produit des matrices W*(u) = tranches d'un champ jacobien (voir parent.py). On observe\nm = 6 points du champ (paires (u*_i, W*_i)), on en cache un, et on demande aux méthodes de\nPRÉDIRE la matrice au point caché — ce que LoRA ne peut structurellement pas faire.\n\nMéthodes (toutes voient les mêmes observations) :\n  - gen_fit     : générateur jacobien à M libre (famille intégrable, K=8 gaussiennes) ;\n  - genfree_fit : MÊME base gaussienne, amplitudes rang-1 libres (lisse, NON intégrable, K=6) ;\n  - hyp_fit     : hypernetwork à sortie libre MLP(u) → d² (lisse, non intégrable, H=8) ;\n  - lerp        : interpolation linéaire des deux matrices adjacentes (baseline géométrique) ;\n  - mean        : moyenne des matrices observées (baseline triviale) ;\n  - nearest     : couche observée la plus proche (baseline triviale).\n\nCritère : erreur relative ‖pred − W*‖_F / ‖W*‖_F au point tenu dehors.\nConfigs : hold = 2 (interpolation) et hold = 5 (extrapolation). Parents : gauss (contrôle\npositif attendu) et mlp (le vrai cas test : intégrable, hors famille gaussienne de l'élève).\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom parent import make_field, D, D_FF\nimport genjac\n\nROOT = Path(__file__).resolve().parents[1]\nM_POINTS = 6\nK_GEN, K_FREE, H_HYP = 8, 6, 8   # gen: 8×(64+32+1)=776 ; genfree: 6×(64+64+32+1)=966 — proches\nADAM_STEPS, LR = 3000, 0.03\nRESTARTS = 3\n\n\n# ------------------------------------------------------------------ générateur jacobien (M libre)\n\ndef _unpack_gen(p, K, d, d_ff):\n    i0 = d_ff * d\n    i1 = i0 + K * d\n    M = p[:i0].reshape(d_ff, d)\n    C = p[i0:i1].reshape(K, d)\n    logR = p[i1:i1 + K]\n    A = p[i1 + K:].reshape(K, d_ff)\n    return M, C, logR, A\n\n\ndef _gen_W(p, u, K, d, d_ff):\n    \"\"\"W(u) = M + Σ_k a_k v_k(u)ᵀ pour un lot u (m,d). Retourne (W (m,d_ff,d), aux).\"\"\"\n    M, C, logR, A = _unpack_gen(p, K, d, d_ff)\n    m = u.shape[0]\n    W = np.repeat(M[None], m, axis=0)\n    aux = []\n    for k in range(K):\n        R = float(np.exp(logR[k]))\n        dvec = u - C[k]\n        s = np.sum(dvec ** 2, axis=1)\n        phi = np.exp(-s / (2 * R * R))\n        aux.append((dvec, s, phi, R))\n        vk = -(phi / R ** 2)[:, None] * dvec          # (m,d)\n        W += np.einsum(\"mi,mj->mij\", np.repeat(A[k][None], m, 0), vk)\n    return W, aux\n\n\ndef _gen_loss_grad(p, u, T, K, d, d_ff):\n    \"\"\"L = Σ_i ½‖W(u_i) − T_i‖²_F ; gradients analytiques en M, C, logR, A (A de dim d_ff).\"\"\"\n    M, C, logR, A = _unpack_gen(p, K, d, d_ff)\n    W, aux = _gen_W(p, u, K, d, d_ff)\n    E = W - T\n    L = 0.5 * float(np.sum(E ** 2))\n    gM = E.sum(axis=0)\n    gC = np.zeros((K, d)); gR = np.zeros(K); gA = np.zeros((K, d_ff))\n    for k in range(K):\n        dvec, s, phi, R = aux[k]\n        q = phi / R ** 2\n        gA[k] = np.einsum(\"mij,mj->i\", E, -(q[:, None] * dvec))     # E · v_k\n        p_ = np.einsum(\"mij,i->mj\", E, A[k])                         # E_iᵀ a_k (m,d)\n        sc = np.einsum(\"md,md->m\", dvec, p_)\n        gC[k] = (q[:, None] * p_).sum(axis=0) - ((phi / R ** 4) * sc) @ dvec\n        gR[k] = -float(np.sum((phi * (s - 2 * R * R) / R ** 4) * sc))\n    return L, np.concatenate([gM.reshape(-1), gC.reshape(-1), gR, gA.reshape(-1)])\n\n\ndef gen_fit(obs_u, obs_W, K, d, d_ff, rng):\n    \"\"\"W(u) = M + Σ_k a_k v_k(u)ᵀ — famille intégrable, M libre, ajustée par Adam.\"\"\"\n    def loss_grad(p):\n        return _gen_loss_grad(p, obs_u, obs_W, K, d, d_ff)\n\n    p0 = np.concatenate([(rng.standard_normal((d_ff, d)) * np.sqrt(2.0 / (d + d_ff))).reshape(-1),\n                         _gauss_init(K, d, d_ff, obs_u, rng)])\n    x, L, _ = genjac.adam(loss_grad, p0, lr=LR, steps=ADAM_STEPS, tol=1e-14)\n    return x\n\n\ndef gen_pred(p, u, K, d, d_ff):\n    return _gen_W(p, u[None], K, d, d_ff)[0][0]\n\n\ndef _gauss_init(K, d, d_ff, U, rng, extra_b=False):\n    \"\"\"Init vivante : centres près des points observés, rayons U(0,5 ; 1,5), amplitudes petites.\"\"\"\n    C = np.stack([U[rng.integers(0, len(U))] + 0.3 / np.sqrt(d) * rng.standard_normal(d)\n                  for _ in range(K)])\n    logR = rng.uniform(np.log(0.5), np.log(1.5), K)\n    a = rng.standard_normal((K, d_ff)) * 0.05\n    parts = [C.reshape(-1), logR, a.reshape(-1)]\n    if extra_b:\n        parts.append((rng.standard_normal((K, d)) * (0.3 / np.sqrt(d))).reshape(-1))\n    return np.concatenate(parts)\n\n\n# ------------------------------------------------------------------ ablation lisse non intégrable\n\ndef genfree_fit(obs_u, obs_W, K, d, d_ff, rng):\n    \"\"\"W(u) = M + Σ_k φ_k(u)·a_k b_kᵀ — même base gaussienne, amplitudes rang-1 libres.\"\"\"\n    m = len(obs_u)\n    i0 = d_ff * d\n\n    def parts(p):\n        q = p[i0:]\n        C = q[:K * d].reshape(K, d); q = q[K * d:]\n        logR = q[:K]; q = q[K:]\n        A = q[:K * d_ff].reshape(K, d_ff)\n        Bv = q[K * d_ff:].reshape(K, d)\n        return p[:i0].reshape(d_ff, d), C, logR, A, Bv\n\n    def loss_grad(p):\n        M, C, logR, A, Bv = parts(p)\n        W = np.repeat(M[None], m, axis=0)\n        phis = []\n        for k in range(K):\n            R = float(np.exp(logR[k]))\n            dvec = obs_u - C[k]\n            phi = np.exp(-np.sum(dvec ** 2, 1) / (2 * R * R))\n            phis.append((phi, dvec, R))\n            for i in range(m):\n                W[i] += phi[i] * np.outer(A[k], Bv[k])\n        E = W - obs_W\n        L = 0.5 * float(np.sum(E ** 2))\n        gM = E.sum(0)\n        gC = np.zeros((K, d)); gR = np.zeros(K)\n        gA = np.zeros((K, d_ff)); gB = np.zeros((K, d))\n        for k in range(K):\n            phi, dvec, R = phis[k]\n            for i in range(m):\n                gA[k] += phi[i] * (E[i] @ Bv[k])\n                gB[k] += phi[i] * (E[i].T @ A[k])\n                dphi = float(A[k] @ E[i] @ Bv[k])\n                gC[k] += dphi * (phi[i] * dvec[i] / R ** 2)\n                gR[k] += dphi * phi[i] * float(dvec[i] @ dvec[i]) / R ** 2\n        return L, np.concatenate([gM.reshape(-1), gC.reshape(-1), gR, gA.reshape(-1), gB.reshape(-1)])\n\n    p0 = np.concatenate([(rng.standard_normal((d_ff, d)) * np.sqrt(2.0 / (d + d_ff))).reshape(-1),\n                         _gauss_init(K, d, d_ff, obs_u, rng, extra_b=True)])\n    x, L, _ = genjac.adam(loss_grad, p0, lr=LR, steps=ADAM_STEPS, tol=1e-14)\n    return x\n\n\ndef genfree_pred(p, u, K, d, d_ff):\n    i0 = d_ff * d\n    M, C, logR, A, Bv = (lambda q: (p[:i0].reshape(d_ff, d),\n                                    q[:K * d].reshape(K, d), q[K * d:K * d + K],\n                                    q[K * d + K:K * d + K + K * d_ff].reshape(K, d_ff),\n                                    q[K * d + K + K * d_ff:].reshape(K, d)))(p[i0:])\n    W = M.copy()\n    for k in range(K):\n        R = float(np.exp(logR[k]))\n        dvec = u - C[k]\n        phi = np.exp(-float(dvec @ dvec) / (2 * R * R))\n        W += phi * np.outer(A[k], Bv[k])\n    return W\n\n\n# ------------------------------------------------------------------ hypernetwork libre (rectangulaire)\n\nclass RectHypernet:\n    \"\"\"MLP(u) → tanh → d_ff·d (sortie libre, biais de sortie libres) — champ lisse non intégrable.\"\"\"\n\n    def __init__(self, d, d_ff, H, rng):\n        self.d, self.d_ff, self.H = d, d_ff, H\n        self.shapes = [((H, d), np.sqrt(1.0 / d)), ((H,), 0.1),\n                       ((d_ff * d, H), np.sqrt(1.0 / H)), ((d_ff * d,), 0.05)]\n        self.params = np.concatenate([(rng.standard_normal(s) * sc).reshape(-1)\n                                      for s, sc in self.shapes])\n\n    def _split(self):\n        i = 0\n        out = []\n        for s, _ in self.shapes:\n            n = int(np.prod(s))\n            out.append(self.params[i:i + n].reshape(s))\n            i += n\n        return out\n\n    def W(self, u):\n        W1, b1, W2, b2 = self._split()\n        h = np.tanh(u @ W1.T + b1)\n        return (h @ W2.T + b2).reshape(-1, self.d_ff, self.d)\n\n    def loss_grad(self, u, T):\n        W1, b1, W2, b2 = self._split()\n        m = u.shape[0]\n        h = np.tanh(u @ W1.T + b1)\n        W = (h @ W2.T + b2).reshape(m, self.d_ff, self.d)\n        E = W - T\n        L = 0.5 * float(np.sum(E ** 2))\n        dG = E.reshape(m, self.d_ff * self.d)\n        gW2 = dG.T @ h\n        gb2 = dG.sum(axis=0)\n        dh = dG @ W2\n        dh_pre = dh * (1 - h ** 2)\n        return L, np.concatenate([(dh_pre.T @ u).reshape(-1), dh_pre.sum(axis=0),\n                                  gW2.reshape(-1), gb2])\n\n    def set(self, p):\n        self.params = p\n\n\ndef hyp_fit(obs_u, obs_W, d, d_ff, rng, H=H_HYP):\n    hyp = RectHypernet(d, d_ff, H, rng)\n\n    def loss_grad(p):\n        hyp.set(p)\n        return hyp.loss_grad(obs_u, obs_W)\n\n    x, L, _ = genjac.adam(loss_grad, hyp.params.copy(), lr=LR, steps=ADAM_STEPS, tol=1e-14)\n    return x\n\n\ndef hyp_pred(p, u, d, d_ff, H=H_HYP):\n    hyp = RectHypernet(d, d_ff, H, np.random.default_rng(0))\n    hyp.set(p)\n    return hyp.W(u[None])[0]\n\n\n# ------------------------------------------------------------------ baselines\n\ndef lerp_pred(obs_u, obs_W, u_hold):\n    \"\"\"Interpolation linéaire entre les deux matrices adjacentes le long de l'axe du champ.\"\"\"\n    e = obs_u[-1] - obs_u[0]\n    e = e / np.linalg.norm(e)\n    t = np.array([float(obs_u[i] @ e) for i in range(len(obs_u))])\n    th = float(u_hold @ e)\n    j = int(np.searchsorted(t, th))\n    j = max(1, min(j, len(t) - 1))\n    f = (th - t[j - 1]) / (t[j] - t[j - 1])\n    f = max(0.0, min(1.0, f))\n    return (1 - f) * obs_W[j - 1] + f * obs_W[j]\n\n\ndef _fit_rmse(p, pred, obs_u, obs_W):\n    err = np.sqrt(np.mean([np.sum((pred(p, obs_u[i]) - obs_W[i]) ** 2) for i in range(len(obs_u))]))\n    return float(err / np.linalg.norm(obs_W[0]))\n\n\ndef main(seed0=0, n_seeds=5):\n    results = []\n    for kind in (\"gauss\", \"mlp\"):\n        for seed in range(seed0, seed0 + n_seeds):\n            field = make_field(kind, seed * 101 + 7)\n            rng = np.random.default_rng(seed * 13 + (3 if kind == \"mlp\" else 5))\n            base_U = field[\"U\"]\n            e = (base_U[-1] - base_U[0]) / np.linalg.norm(base_U[-1] - base_U[0])\n            ts = np.linspace(-0.9, 1.9, M_POINTS)\n            U = np.stack([base_U.mean(0) + t * e + 0.05 / np.sqrt(D) * rng.standard_normal(D)\n                          for t in ts])\n            Ws = np.stack([field[\"Wstar\"](u) for u in U])\n            for hold in (2, 5):\n                idx = [i for i in range(M_POINTS) if i != hold]\n                obs_u, obs_W = U[idx], Ws[idx]\n                u_h, W_h = U[hold], Ws[hold]\n                tn = np.linalg.norm(W_h)\n                row = {\"kind\": kind, \"seed\": seed, \"hold\": hold}\n                row[\"mean\"] = float(np.linalg.norm(obs_W.mean(0) - W_h) / tn)\n                row[\"nearest\"] = float(min(np.linalg.norm(obs_W[i] - W_h) / tn\n                                           for i in range(len(obs_W))))\n                row[\"lerp\"] = float(np.linalg.norm(lerp_pred(obs_u, obs_W, u_h) - W_h) / tn)\n                for name, fit, pred in (\n                    (\"gen\", lambda r: gen_fit(obs_u, obs_W, K_GEN, D, D_FF, r),\n                     lambda p, u: gen_pred(p, u, K_GEN, D, D_FF)),\n                    (\"genfree\", lambda r: genfree_fit(obs_u, obs_W, K_FREE, D, D_FF, r),\n                     lambda p, u: genfree_pred(p, u, K_FREE, D, D_FF)),\n                    (\"hyp\", lambda r: hyp_fit(obs_u, obs_W, D, D_FF, r),\n                     lambda p, u: hyp_pred(p, u, D, D_FF)),\n                ):\n                    best, best_fit = None, np.inf\n                    for rs in range(RESTARTS):\n                        r2 = np.random.default_rng((seed * 977 + hold * 31 + rs * 7 + hash(name) % 997) % 2 ** 31)\n                        p = fit(r2)\n                        fe = _fit_rmse(p, pred, obs_u, obs_W)\n                        if fe < best_fit:\n                            best_fit, best = fe, p\n                    row[name] = float(np.linalg.norm(pred(best, u_h) - W_h) / tn)\n                    row[name + \"_fit\"] = float(best_fit)\n                results.append(row)\n                print(f\"[e1] {kind}/s{seed}/hold{hold}: \" +\n                      \" \".join(f\"{k}={row[k]:.4f}\" for k in (\"gen\", \"genfree\", \"hyp\", \"lerp\", \"mean\")),\n                      flush=True)\n    out = ROOT / \"results\"\n    out.mkdir(exist_ok=True)\n    (out / \"e1_field.json\").write_text(json.dumps(results, indent=1))\n    print(\"saved -> results/e1_field.json\")\n\n\nif __name__ == \"__main__\":\n    main()\n"